  const input = inputs[i].json, req = requests[i].json;
  const requestKey = JSON.stringify([req.deptId,req.announcementType,req.announceDate]);
  if (seenRequests.has(requestKey)) throw new Error('Duplicate department/stage/date request.');
  seenRequests.add(requestKey);
  const channel = input.rss?.channel;
  if (!channel || channel.countbyday === undefined) throw new Error('Missing RSS channel/countbyday for '+req.deptId+'/'+req.announcementType);
  const reportedCount = Number(text(channel.countbyday));
  const stats = input.titleFilter;
  if (!Number.isInteger(reportedCount) || reportedCount<0) throw new Error('Invalid countbyday.');
  if (!stats || ![stats.inputCount,stats.matchedCount,stats.rejectedCount].every(n=>Number.isInteger(n)&&n>=0) || stats.matchedCount+stats.rejectedCount!==stats.inputCount) throw new Error('Invalid title filter counts.');
  const items = Array.isArray(channel.item)?channel.item:channel.item?[channel.item]:[];
  if (items.length!==stats.matchedCount) throw new Error('Filtered RSS items do not match keyword counts.');
  const expectedDate = req.announceDate.replace(/^(\d{4})(\d{2})(\d{2})$/,'$1-$2-$3');
  for (const item of items) if (text(item.pubDate||item.pubdate).slice(0,10)!==expectedDate) throw new Error('Feed returned an unexpected publication date.');
  dates.add(req.announceDate);versions.add(stats.version);
  if (!departments.has(req.deptId)) departments.set(req.deptId,{departmentId:req.deptId,departmentName:req.departmentName,...counts()});
  if (!stages.has(req.announcementType)) stages.set(req.announcementType,{announcementType:req.announcementType,announcementLabel:req.announcementLabel,...counts()});
  for (const summary of [totals,departments.get(req.deptId),stages.get(req.announcementType)]) {
    summary.requestCount++;
    summary.reportedCount+=reportedCount;
    summary.itemsReceived+=stats.inputCount;
    summary.keywordMatchedCount+=stats.matchedCount;
    summary.keywordRejectedCount+=stats.rejectedCount;
    if (stats.inputCount!==reportedCount) summary.incompleteRequestCount++;
  }
}
const complete = totals.incompleteRequestCount===0;
return [{json:{
